import {test,expect} from 'bun:test';
import {payments,reset,booked,effectivePayments} from './payments';
import {annualReport} from './report';
import {splitCheckout,wholeCheckout,reclaimReservation} from './checkout';

test('annual report uses effective payments for the requested year',()=>{
  reset();
  payments.push(
    {id:'included',posted:true,paidAt:'2025-01-01',cents:100},
    {id:'rejected',posted:true,paidAt:'2025-02-01',rejectedAt:'2026-01-01',cents:200},
    {id:'unposted',posted:false,paidAt:'2025-03-01',cents:400},
    {id:'other-year',posted:true,paidAt:'2024-01-01',cents:800},
  );
  expect(annualReport(2025).cents).toBe(effectivePayments(2025).reduce((sum,p)=>sum+p.cents,0));
  expect(annualReport(2025).cents).toBe(100);
});

test('split bookings prevent whole retries and reservation release',()=>{
  reset();
  splitCheckout('one',[40,60]);
  expect(wholeCheckout('one',100).status).toBe('already-booked');
  expect(reclaimReservation('one')).toBe(false);
  expect(booked.size).toBe(2);
  expect(reclaimReservation('on')).toBe(true);
  expect(wholeCheckout('other',50).status).toBe('booked');
  expect(reclaimReservation('other')).toBe(false);
});

