import {booked} from './payments';

function paymentKey(line:string, part?:number){
  return `payment:${line}${part === undefined ? '' : `:part:${part}`}`;
}

function isPaymentKeyForLine(key:string, line:string){
  if(key === paymentKey(line)) return true;
  const prefix = `${paymentKey(line)}:part:`;
  if(!key.startsWith(prefix)) return false;
  const part = key.slice(prefix.length);
  return /^(0|[1-9]\d*)$/.test(part);
}

function hasBooking(line:string){
  for(const key of booked.keys()) if(isPaymentKeyForLine(key,line)) return true;
  return false;
}

export function splitCheckout(line:string,parts:number[]){parts.forEach((cents,i)=>booked.set(paymentKey(line,i),cents));}
export function wholeCheckout(line:string,cents:number){if(hasBooking(line))return {status:'already-booked'};booked.set(paymentKey(line),cents);return {status:'booked'};}
export function reclaimReservation(line:string){return !hasBooking(line);}

